internal::Polygon_2 poly1, poly2;
for (const auto& p : P1.vectorPoints()) {
    poly1.push_back(internal::Point_2(p.x, p.y));
}
for (const auto& p : P2.vectorPoints()) {
    poly2.push_back(internal::Point_2(p.x, p.y));
}

internal::Pwh_list_2 result_list;
CGAL::set_difference(poly1, poly2, std::back_inserter(result_list));

std::vector<PolygonWithHoles2d> result;
for (const auto& pwh : result_list) {
    PolygonWithHoles2d res_poly;

    // Outer boundary
    for (auto it = pwh.outer_boundary().begin(); it != pwh.outer_boundary().end(); ++it) {
        double x, y;
        internal::getCoordinates(*it, x, y);
        res_poly.outer_boundary.push_back(Point2d(x, y));
    }

    // Holes
    for (auto hole_it = pwh.holes_begin(); hole_it != pwh.holes_end(); ++hole_it) {
        std::vector<Point2d> hole;
        for (auto it = hole_it->begin(); it != hole_it->end(); ++it) {
            double x, y;
            internal::getCoordinates(*it, x, y);
            hole.push_back(Point2d(x, y));
        }
        res_poly.holes.push_back(hole);
    }
    result.push_back(res_poly);
}

return result;

